import sys

# 按传入顺序合并配置，后加载的覆盖先加载的
merged = {}
args = sys.argv[1:]
i = 0
while i < len(args):
    if args[i] == "-c":
        # 简化：直接读取 yaml 中的 host
        with open(args[i + 1]) as f:
            for line in f:
                if "host:" in line:
                    merged["host"] = line.split(":", 1)[1].strip()
        i += 2
    else:
        i += 1
print("db host: " + merged["host"])

#!/bin/bash
# 依次加载配置，后加载的覆盖先加载的（a → c → b）
python app.py -c config.a.yaml -c config.c.yaml -c config.b.yaml

