    return (new DateTimeImmutable($date))->modify("+{$months} months")->format('Y-m-d');
}

requirements.referenceSolution:
function addMonths(string $date, int $months): string {
    $t = new DateTimeImmutable($date);
    $y = (int)$t->format('Y');
    $m = (int)$t->format('n');
    $d = (int)$t->format('j');
    $total = $y * 12 + ($m - 1) + $months;
    $ny = intdiv($total, 12);
    $nm = $total % 12 + 1;
    $last = (int)(new DateTimeImmutable(sprintf('%04d-%02d-01', $ny, $nm)))->format('t');
    return sprintf('%04d-%02d-%02d', $ny, $nm, min($d, $last));
}

