#### 初始代码
```js
class TaskQueue {
  static VALID_TRANSITIONS = {
    pending: ["running", "cancelled"],
    running: ["completed", "failed", "cancelled"],
    completed: [],
    failed: ["retrying"],
    retrying: ["pending"],
    cancelled: [],
  };

  constructor() {
    this.tasks = new Map();
    this._idCounter = 0;
  }

  addTask(name, payload) {
    this._idCounter++;
    const taskId = this._idCounter;
    this.tasks.set(taskId, {
      id: taskId, name, payload, status: "pending", attempts: 0,
    });
    return taskId;
  }

  transition(taskId, newStatus) {
    const task = this.tasks.get(taskId);
    if (!task) throw new Error(`Task ${taskId} not found`);
    const current = task.status;
    const allowed = TaskQueue.VALID_TRANSITIONS[current] ?? [];
    if (!allowed.includes(newStatus)) {
      throw new Error(`Cannot transition from ${current} to ${newStatus}`);
    }
    task.status = newStatus;
    return true;
  }

  getRunnable() {
    return [...this.tasks.values()].filter(t => t.status === "pending");
  }

  markFailed(taskId) {
    this.transition(taskId, "failed");
  }

  retry(taskId) {
    const task = this.tasks.get(taskId);
    if (task.status !== "failed") {
      throw new Error("Can only retry failed tasks");
    }
    task.attempts++;
    this.transition(taskId, "retrying");
  }
}
```

