class InventoryService {
  constructor() {
    this.stock = new Map();
    this.reservations = new Map();
  }

  setStock(productId, quantity) {
    this.stock.set(productId, quantity);
  }

  getAvailable(productId) {
    const total = this.stock.get(productId) ?? 0;
    const reserved = [...this.reservations.values()]
      .filter(r => r.productId === productId)
      .reduce((sum, r) => sum + r.quantity, 0);
    return total - reserved;
  }

  reserve(orderId, productId, quantity) {
    if (this.getAvailable(productId) < quantity) {
      throw new Error(`Insufficient stock for ${productId}`);
    }
    this.reservations.set(orderId, { productId, quantity });
    return true;
  }

  confirm(orderId) {
    const reservation = this.reservations.get(orderId);
    if (!reservation) throw new Error(`Order ${orderId} not found`);
    this.reservations.delete(orderId);
    const current = this.stock.get(reservation.productId) ?? 0;
    this.stock.set(reservation.productId, current - reservation.quantity);
    return true;
  }

  cancel(orderId) {
    return this.reservations.delete(orderId);
  }
}
```

