class MessageQueue {
  constructor() {
    this.queues = new Map(); // topic -> message[]
    this.consumers = new Map(); // topic -> consumer[]
  }

  publish(topic, message) {
    if (!this.queues.has(topic)) this.queues.set(topic, []);
    this.queues.get(topic).push({ id: Date.now() + Math.random(), payload: message, timestamp: Date.now() });
    this._deliver(topic);
  }

  subscribe(topic, handler) {
    if (!this.consumers.has(topic)) this.consumers.set(topic, []);
    this.consumers.get(topic).push(handler);
  }

  _deliver(topic) {
    const messages = this.queues.get(topic) ?? [];
    const handlers = this.consumers.get(topic) ?? [];
    for (const handler of handlers) {
      for (const msg of messages) {
        try {
          handler(msg.payload);
        } catch (err) {
          console.error("Consumer error:", err);
        }
      }
    }
    // 清空队列 — BUG: 第一个 handler 后队列被清空
    this.queues.set(topic, []);
  }

  getQueueLength(topic) {
    return this.queues.get(topic)?.length ?? 0;
  }
}
```

